{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Choose the CT scan",
      "simple": "Select the CT volume of the patient you want to process.",
      "detailed": "This is the starting image that will be used for all bone and orbit measurements. Pick the CT volume that best shows the facial bones and the fractured orbit, because every later reconstruction step will be based on this scan."
    },
    {
      "step_id": "cb_step_2",
      "title": "Create the orbital region box",
      "simple": "Create a new empty ROI/box and name it Orbital_Region.",
      "detailed": "The ROI defines the area of the CT scan that will be cut out for focused processing. By limiting the working area to just the orbits, later segmentation is faster and less affected by the rest of the skull. Create an empty ROI and name it Orbital_Region."
    },
    {
      "step_id": "cb_step_3",
      "title": "Adjust the box around the orbit",
      "simple": "Move and resize the ROI in the slice views so it encloses the fractured orbital area.",
      "detailed": "The ROI should tightly surround the orbit, including the orbital walls and any displaced bone fragments. This boundary determines how much bone will be included in the cut volume, so make sure the whole orbital region is inside the box before continuing."
    },
    {
      "step_id": "cb_step_4",
      "title": "Confirm the region box",
      "simple": "Select the Orbital_Region ROI you just created.",
      "detailed": "The workflow needs to know exactly which ROI to use when cutting the CT volume. Choose the ROI that surrounds the orbit so the cut is applied to the correct region."
    },
    {
      "step_id": "cb_step_5",
      "title": "Cut the CT to the orbital region",
      "simple": "Click the button to cut the volume using the ROI.",
      "detailed": "This trims the CT scan down to the orbital region, creating a focused working volume for bone segmentation. Cropping away the rest of the scan makes it easier to separate the fine orbital bone from surrounding tissue and reduces processing time."
    },
    {
      "step_id": "cb_step_6",
      "title": "Start a bone segmentation",
      "simple": "Create a new segmentation for the cut orbital volume and name it Bone_Segmentation.",
      "detailed": "Segmentation is how the bone is separated from the CT scan for reconstruction. This new segmentation will hold all the bone and orbit labels used in later steps, so give it a clear name."
    },
    {
      "step_id": "cb_step_7",
      "title": "Add the bone segment",
      "simple": "Add a new segment and rename it Bone_Segment.",
      "detailed": "A segment is a single labeled object inside the segmentation. This bone segment will be filled with the thresholded bone, so it must be present before applying the threshold."
    },
    {
      "step_id": "cb_step_8",
      "title": "Open the threshold tool",
      "simple": "Open the Threshold tool in the Segment Editor.",
      "detailed": "Thresholding selects bone by its brightness on the CT scan. Opening this tool lets you set the Hounsfield-style range that separates bone from soft tissue."
    },
    {
      "step_id": "cb_step_9",
      "title": "Set the bone threshold range",
      "simple": "Adjust the threshold slider so the bone is highlighted, then continue.",
      "detailed": "You want the highlighted area to cover the cortical and trabecular bone of the orbital region without including too much soft tissue or noise. A good threshold range will make the bone appear clearly and cleanly in the segment before you apply it."
    },
    {
      "step_id": "cb_step_10",
      "title": "Apply the bone threshold",
      "simple": "Click Apply to turn the highlighted bone into the Bone_Segment.",
      "detailed": "Applying the threshold fills the selected segment with all voxels in the chosen range, creating an initial bone segmentation of the orbital region. This is the raw bone data that will be used to reconstruct the intact and fractured orbit."
    },
    {
      "step_id": "cb_step_11",
      "title": "Select the bone segmentation",
      "simple": "Select the bone segmentation you just created.",
      "detailed": "The reconstruction step needs the bone segmentation to build a full bone model. Choose the segmentation that contains the Bone_Segment so the correct bone data is used."
    },
    {
      "step_id": "cb_step_12",
      "title": "Rebuild the full bone",
      "simple": "Click the Reconstruct full bone button.",
      "detailed": "This creates a complete anatomical bone volume from the thresholded segmentation, providing a reference model of the orbital bone structure. The full bone reconstruction is the foundation for comparing and repairing the fractured side."
    },
    {
      "step_id": "cb_step_13",
      "title": "Choose the fractured side",
      "simple": "Pick the colored box that is over the fractured orbit: Red for the right side, Blue for the left side.",
      "detailed": "The reconstruction must know which orbit is fractured so it can use the correct mirrored healthy anatomy as a guide. Look at the 3D view and select the color that matches the side of the injury."
    },
    {
      "step_id": "cb_step_14",
      "title": "Segment the orbit",
      "simple": "Click the Segment orbit button.",
      "detailed": "This isolates the fractured orbit from the full bone model so it can be reconstructed separately. The resulting orbit segment defines the damaged anatomy that will be repaired using the mirrored healthy side."
    },
    {
      "step_id": "cb_step_15",
      "title": "Reconstruct the fracture",
      "simple": "Click the Reconstruct fractured button.",
      "detailed": "This final step generates the repaired orbital reconstruction, using the healthy opposite side as a template to restore the normal shape of the fractured orbit. The result is the surgical plan for repositioning bone fragments and guiding orbital wall repair."
    }
  ]
}
